descriptor.templateCss:
:host{display:block;border-radius:inherit;width:100%;height:100%;min-width:0;min-height:0;overflow:hidden}
*{box-sizing:border-box}
.fg-root{border-radius:inherit;--fg-text:#edf3f8;--fg-muted:#91a2b3;--fg-track:#293846;--fg-accent:#f2c300;--fg-needle:#ffffff;--fg-hub-dot:#101820;position:relative;width:100%;height:100%;min-height:0;padding:10px 14px 8px;display:flex;flex-direction:column;align-items:stretch;justify-content:center;overflow:hidden;background:transparent;color:var(--fg-text);font-family:Roboto,Arial,sans-serif}
.fg-industrial{--fg-text:#edf3f8;--fg-muted:#91a2b3;--fg-track:#293846;--fg-accent:#f2c300;--fg-needle:#ffffff;--fg-hub-dot:#101820;background:radial-gradient(ellipse at 50% 80%,rgba(242,195,0,.07),transparent 62%),linear-gradient(145deg,#17232e,#101820)}
.fg-light{--fg-text:#263445;--fg-muted:#778596;--fg-track:#e4e9ef;--fg-accent:#d99a00;--fg-needle:#1f2d3d;--fg-hub-dot:#ffffff;background:linear-gradient(145deg,#fff,#f4f7fa)}
.fg-header{width:100%;display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:22px;margin-bottom:0;z-index:2;flex:0 0 auto}
.fg-heading{display:flex;align-items:center;gap:8px;min-width:0}
.fg-label{font-size:13px;font-weight:650;letter-spacing:.25px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fg-status{font-size:9px;line-height:16px;font-weight:700;letter-spacing:.5px;text-transform:uppercase;padding:0 8px;border-radius:20px;background:rgba(52,185,125,.14);color:#42c88b;white-space:nowrap}
.fg-gauge-wrap{position:relative;width:100%;flex:1 1 auto;min-height:0;min-width:0;margin:0 auto;display:flex;align-items:center;justify-content:center}
.fg-stage{position:relative;width:100%;aspect-ratio:4/3;max-width:100%;max-height:100%;flex:0 0 auto}
.fg-svg{display:block;position:absolute;left:0;top:0;width:100%;height:100%;overflow:visible}
.fg-track{fill:none;stroke:var(--fg-track);stroke-width:19;stroke-linecap:butt}
.fg-segment{fill:none;stroke-width:19;stroke-linecap:butt}
.fg-ticks{fill:var(--fg-muted);font-size:9px;font-weight:500}
.fg-needle{color:var(--fg-needle);transform-box:view-box;transform-origin:160px 115px;transition:transform .7s cubic-bezier(.22,.8,.3,1);filter:drop-shadow(0 0 2px rgba(0,0,0,.55))}
.fg-needle-body{fill:currentColor;stroke:currentColor;stroke-width:1;stroke-linejoin:round}
.fg-needle-line{fill:none;stroke:currentColor;stroke-width:3;stroke-linecap:round}
.fg-needle-marker{fill:currentColor}
.fg-hub{fill:currentColor}
.fg-hub-dot{fill:var(--fg-hub-dot)}
.fg-bottom-content{position:absolute;left:50%;top:80%;transform:translate(-50%,-50%);max-width:62%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;text-align:center;pointer-events:none}
.fg-icon{display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;font-size:18px;line-height:18px;color:var(--fg-accent);margin-bottom:1px}
.fg-icon .mat-icon,.fg-icon mat-icon,.fg-icon svg{width:18px;height:18px;font-size:18px;line-height:18px;color:inherit;fill:currentColor}
.fg-light .fg-icon{color:#d99a00}
.fg-value-row{display:flex;align-items:baseline;justify-content:center;white-space:nowrap}
.fg-value{line-height:1.02;font-weight:750;letter-spacing:-1.2px;font-variant-numeric:tabular-nums;color:var(--fg-text)}
.fg-unit{line-height:1;font-weight:650;color:var(--fg-muted)}
.fg-caption{font-size:8px;line-height:11px;color:var(--fg-muted);margin-top:2px;letter-spacing:.35px;text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.fg-footer{width:100%;display:flex;justify-content:space-between;align-items:center;color:var(--fg-muted);font-size:10px;font-variant-numeric:tabular-nums;padding:0 8px;flex:0 0 auto}
.fg-no-data{position:absolute;left:0;right:0;bottom:5px;text-align:center;color:var(--fg-muted);font-size:10px;pointer-events:none}
@media(max-height:170px){.fg-root{padding:4px}.fg-header{min-height:16px}.fg-label{font-size:10px}.fg-icon,.fg-icon .mat-icon,.fg-icon mat-icon,.fg-icon svg{font-size:13px;width:13px;height:13px;line-height:13px}.fg-footer{font-size:8px}}

descriptor.controllerScript:
var fg={dead:false};
var FG_DEF=[{c:'#D94B45',t:'CRÍTICO',s:'#FF5A52'},{c:'#E6A23C',t:'BAJO',s:'#FF9A3D'},{c:'#E8C547',t:'MEDIO',s:'#F2C300'},{c:'#38A879',t:'NORMAL',s:'#42C88B'}];
function fgRgba(hex,a){var h=String(hex||'').trim();var m=/^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(h);if(!m)return 'rgba(66,200,139,'+a+')';var x=m[1];if(x.length===3)x=x[0]+x[0]+x[1]+x[1]+x[2]+x[2];var n=parseInt(x,16);return 'rgba('+((n>>16)&255)+','+((n>>8)&255)+','+(n&255)+','+a+')';}
function fgNum(v,d){var n=Number(v);return isFinite(n)&&v!==null&&v!==''?n:d;}
function fgClamp(v,a,b){return Math.max(a,Math.min(b,v));}
function fgPoint(cx,cy,r,a){var rad=a*Math.PI/180;return{x:cx+r*Math.cos(rad),y:cy+r*Math.sin(rad)};}
function fgArc(cx,cy,r,a0,a1){var p0=fgPoint(cx,cy,r,a0),p1=fgPoint(cx,cy,r,a1);var sweep=a1>=a0?1:0;var large=Math.abs(a1-a0)>180?1:0;return'M '+p0.x.toFixed(3)+' '+p0.y.toFixed(3)+' A '+r+' '+r+' 0 '+large+' '+sweep+' '+p1.x.toFixed(3)+' '+p1.y.toFixed(3);}
function fgNeedle(style,len,cx,cy){
 var f=function(n){return n.toFixed(2);};
 var o={path:'',filled:true,marker:'',hub:0,dot:0};
 if(style==='none')return o;
 if(style==='thin'){
   o.path='M '+f(cx-14)+' '+f(cy)+' L '+f(cx+len)+' '+f(cy);o.filled=false;o.hub=5.5;o.dot=0;return o;
 }
 o.path='M '+f(cx-16)+' '+f(cy-3)+' L '+f(cx)+' '+f(cy-5)+' L '+f(cx+len)+' '+f(cy)+' L '+f(cx)+' '+f(cy+5)+' L '+f(cx-16)+' '+f(cy+3)+' Z';
 o.hub=9;o.dot=3.2;
 if(style==='pointer'){o.marker='M '+f(cx+107)+' '+f(cy)+' L '+f(cx+121)+' '+f(cy-7.5)+' L '+f(cx+121)+' '+f(cy+7.5)+' Z';}
 return o;
}
function fgBuild(){
 var ctx=self.ctx,s=ctx.settings||{},d=ctx.data||[];
 var min=fgNum(s.minValue,0),max=fgNum(s.maxValue,100);
 if(max<=min)max=min+1;
 // Last value: último punto de la primera serie
 var raw=null;
 if(d.length&&d[0]&&Array.isArray(d[0].data)&&d[0].data.length){raw=d[0].data[d[0].data.length-1][1];}
 var has=raw!==null&&raw!==undefined&&raw!==''&&isFinite(Number(raw));
 var val=has?Number(raw):min;
 var ratio=(fgClamp(val,min,max)-min)/(max-min);
 // Arco de 234°: la abertura de 126° queda siempre abajo.
 var right=s.startSide==='right';
 var start=right?27:153,end=right?-207:387;
 var cx=160,cy=115,r=94;
 var track=fgArc(cx,cy,r,start,end);
 var colors=Array.isArray(s.sections)&&s.sections.length?s.sections:[{color:'#D94B45'},{color:'#E6A23C'},{color:'#E8C547'},{color:'#38A879'}];
 var n=Math.min(12,colors.length),segs=[];
 for(var i=0;i<n;i++){
   var a=start+(end-start)*(i/n),b=start+(end-start)*((i+1)/n);
   segs.push({path:fgArc(cx,cy,r,a,b),color:colors[i].color||'#38A879'});
 }
 var ticks=[];
 if(s.showScale){
   for(var j=0;j<=4;j++){
     var ta=start+(end-start)*(j/4),p=fgPoint(cx,cy,r+18,ta);
     ticks.push({x:p.x.toFixed(1),y:(p.y+3).toFixed(1),label:String(Math.round(min+(max-min)*j/4))});
   }
 }
 // Aguja
 var ns=['classic','thin','pointer','none'].indexOf(s.needleStyle)>=0?s.needleStyle:'classic';
 var nlen=fgClamp(fgNum(s.needleLength,92),40,112);
 var nd=fgNeedle(ns,nlen,cx,cy);
 var angle=start+(end-start)*ratio;
 var needleColor=(s.needleColorAuto===false&&s.needleColor)?s.needleColor:null;
 // Tamaño disponible para el gauge (el texto queda anclado al mismo cuadro que el SVG)
 var W=fgNum(ctx.width,0),H=fgNum(ctx.height,0);
 var showLabel=s.showLabel!==false;
 var stageW=null,stageH=null,scale=1;
 if(W>0&&H>0){
   var aw=W-28,ah=H-18-(showLabel?22:0)-(s.showMinMax===true?16:0);
   if(H<=170){aw=W-8;ah=H-8-(showLabel?16:0)-(s.showMinMax===true?14:0);}
   scale=fgClamp(Math.min(aw/320,ah/240),.25,3);
   stageW=Math.floor(320*scale);stageH=Math.floor(240*scale);
 }
 var valuePx=s.valueSizeMode==='fixed'
   ? fgClamp(fgNum(s.valueSize,37),10,160)
   : fgClamp(37*scale*fgNum(s.valueScale,100)/100,10,200);
 var unitPx=Math.max(7,valuePx*fgClamp(fgNum(s.unitScale,38),15,100)/100);
 var decimals=fgClamp(fgNum(s.decimals,1),0,4);
 var display=has?val.toFixed(decimals):'—';
 var idx=has?Math.min(n-1,Math.floor(ratio*n)):0;
 var seg=colors[idx]||{},dflt=FG_DEF[idx]||FG_DEF[FG_DEF.length-1];
 var status=has?((seg.statusText!==undefined&&seg.statusText!==null)?String(seg.statusText):dflt.t):'';
 var statusColor=seg.statusColor||dflt.s;
 var statusBg=fgRgba(statusColor,.16);
 var br=(ctx.widgetConfig&&ctx.widgetConfig.borderRadius)||null;
 self.ctx.$scope.vm={
   borderRadius:br,theme:s.theme||'industrial',label:s.label||'Fuel Level',showLabel:showLabel,
   showIcon:s.showIcon===true,icon:(typeof s.icon==='string'&&s.icon.trim())?s.icon.trim():'local_gas_station',
   showStatus:s.showStatus===true,status:status,statusColor:statusColor,statusBg:statusBg,
   trackPath:track,segments:segs,ticks:ticks,showScale:s.showScale===true,
   needleStyle:ns,needlePath:nd.path,needleFilled:nd.filled,markerPath:nd.marker,hubRadius:nd.hub,hubDot:nd.dot,
   needleTransform:'rotate('+angle.toFixed(2)+'deg)',needleColor:needleColor,
   stageW:stageW,stageH:stageH,valueFontPx:Math.round(valuePx*10)/10,unitFontPx:Math.round(unitPx*10)/10,
   unitGap:fgClamp(fgNum(s.unitGap,4),0,30),
   displayValue:display,unit:s.unit||'',showCaption:s.showCaption===true,caption:s.caption||'',
   showMinMax:s.showMinMax===true,minLabel:String(min),maxLabel:String(max),
   hasData:has,noDataText:s.noDataText||'Sin datos'
 };
 if(ctx.detectChanges)ctx.detectChanges();
}
self.onInit=function(){fg.dead=false;self.ctx.$scope.vm={theme:'industrial',segments:[],ticks:[],trackPath:'',displayValue:'—',hasData:false,needleStyle:'none'};fgBuild();};
self.onDataUpdated=function(){if(!fg.dead)fgBuild();};
self.onLatestDataUpdated=function(){if(!fg.dead)fgBuild();};
self.onResize=function(){if(!fg.dead)fgBuild();};
self.onDestroy=function(){fg.dead=true;};
self.typeParameters=function(){return{maxDatasources:1,maxDataKeys:1,datasourcesOptional:false,dataKeysOptional:false,previewWidth:'360px',previewHeight:'280px'};};
